"Netflix","genres":["Drama"],"status":"published"},{"title_kr":"나빌레라","title_en":"Navillera","aliases":["나빌레라","Navillera"],"year":2021,"network":"tvN","genres":["Drama"],"status":"published"},{"title_kr":"알고있지만","title_en":"Nevertheless","aliases":["알고있지만","Nevertheless"],"year":2021,"network":"Netflix","genres":["Drama"],"status":"published"},{"title_kr":"아기상어 올리와 윌리엄","title_en":"Baby Shark''s Big Show!","aliases":["아기상어 올리와 윌리엄","Baby Shark''s Big Show!","아기상어올리와윌리엄"],"year":2020,"network":"Nickelodeon","genres":["Drama"],"status":"published"},{"title_kr":"편의점 샛별이","title_en":"Backstreet Rookie","aliases":["편의점 샛별이","Backstreet Rookie","편의점샛별이"],"year":2020,"network":"SBS","genres":["Drama"],"status":"published"},{"title_kr":"도도솔솔라라솔","title_en":"Do Do Sol Sol La La Sol","aliases":["도도솔솔라라솔","Do Do Sol Sol La La Sol"],"year":2020,"network":"KBS2","genres":["Drama"],"status":"published"},{"title_kr":"인간수업","title_en":"Extracurricular","aliases":["인간수업","Extracurricular"],"year":2020,"network":"Netflix","genres":["Drama"],"status":"published"},{"title_kr":"나 홀로 그대","title_en":"My Holo Love","aliases":["나 홀로 그대","My Holo Love","나홀로그대"],"year":2020,"network":"Netflix","genres":["Drama"],"status":"published"}]'::jsonb) AS x(title_kr text, title_en text, aliases text[], year int, network text, genres text[], status text)) INSERT INTO public.dramas (title_kr, title_en, aliases, year, network, genres, status) SELECT title_kr, title_en, aliases, year, network, genres, status FROM incoming i WHERE NOT EXISTS (SELECT 1 FROM public.dramas d WHERE lower(d.title_en)=lower(i.title_en) OR d.title_kr=i.title_kr);